const tokenDetailsCache = new cacheUtils.LRUCache<
  string,
  IFetchTokenDetailItem
>({
  max: 100,
  ttl: timerUtils.getTimeDurationMs({ minute: 10 }),
  ttlAutopurge: true,
});

// Shared with the aggregate Overview tab, which resolves the concrete member
// network / derive type before delegating here.
export async function pushSwapFromTokenDetails({
  navigation,
  token,
  networkId,
  networkLogoURI,
  deriveType,
  walletType,
  isSoftwareWalletOnlyUser,
}: {
  navigation: IAppNavigation;
  token: {
    address: string;
    symbol: string;
    isNative?: boolean;
    decimals: number;
    name?: string;
    logoURI?: string;
    balanceMultiplier?: string;
  };
  networkId: string;
  networkLogoURI?: string;
  deriveType?: IAccountDeriveTypes;
  walletType?: string;
  isSoftwareWalletOnlyUser: boolean;
}) {
  if (
    isSwapEntryDisabledToken({
      contractAddress: token.address,
      isNative: token.isNative,
      networkId,
    })
  ) {
    return;
  }

  // Swap has no end-to-end scaled-UI (rebase) support yet — the ISwapToken
  // pipeline treats every amount as raw. The entries are disabled for these
  // tokens; re-check here so no trigger path can seed Swap with a basis out
  // of sync with the wallet display. A multiplier of exactly 1 is the
  // documented no-op and must not block.
  if (tokenRebaseUtils.isScalingBalanceMultiplier(token.balanceMultiplier)) {
    return;
  }
  const importFromToken: ISwapToken = {
    contractAddress: token.address,
    symbol: token.symbol,
    networkId,
    isNative: token.isNative,
    decimals: token.decimals,
    name: token.name,
    logoURI: token.logoURI,
    networkLogoURI,
  };
  let importToToken = getSwapConfiguredDefaultToToken(importFromToken);
  try {
    const { isSupportSwap, isSupportCrossChain } =
      await backgroundApiProxy.serviceSwap.checkSupportSwap({
        networkId,
      });
    if (!importToToken && !isSupportSwap && isSupportCrossChain) {
      importToToken = getSwapBridgeDefaultToToken(importFromToken);
    }
  } catch {
    // Keep the existing Swap fallback if capability refresh fails.
  }

  defaultLogger.wallet.walletActions.actionTrade({
    walletType: walletType ?? '',
    networkId,
    source: 'tokenDetails',
    tradeType: ESwapTabSwitchType.SWAP,
    isSoftwareWalletOnlyUser,
  });
  navigation.pushModal(EModalRoutes.SwapModal, {
    screen: EModalSwapRoutes.SwapMainLand,
    params: {
      importNetworkId: networkId,
      importFromToken,
      importToToken,
      importDeriveType: deriveType,
      swapTabSwitchType: ESwapTabSwitchType.SWAP,
      swapSource: ESwapSource.TOKEN_DETAIL,
    },
  });
}

type ITokenDetailsAddressBlockProps = {
  shouldShow: boolean;
  label: string;
  address: string;
  onPress: () => void;
  testID?: string;
  disabled?: boolean;
};

const TokenDetailsAddressBlock = memo(
  ({
    shouldShow,
    label,
    address,
    onPress,
    testID,
    disabled,
  }: ITokenDetailsAddressBlockProps) => {
    if (!shouldShow) {
      return null;
    }

    return (
      <>
        <Divider />
        <YStack
          testID={testID}
          userSelect="none"
          onPress={onPress}
          opacity={disabled ? 0.5 : 1}
          px="$5"
          py="$3"
          gap="$1"
          {...listItemPressStyle}
        >
          <SizableText size="$bodyMd" color="$textSubdued">
            {label}
          </SizableText>
          <XStack gap="$4">
            <SizableText
              size="$bodyMd"
              color="$text"
              flexShrink={1}
              $platform-web={{
                wordBreak: 'break-word',
              }}
            >
              {address}
            </SizableText>
            <Icon
              name="Copy3Outline"
              color="$iconSubdued"
              size="$5"
              flexShrink={0}
              marginLeft="auto"
            />
          </XStack>
        </YStack>
      </>
    );
  },
);
TokenDetailsAddressBlock.displayName = 'TokenDetailsAddressBlock';

function TokenDetailsHeaderContent({
  focusParam,
  ...props
}: IProps & { focusParam: boolean }) {
  const {
    accountId,
    networkId,
    walletId,
    tokenInfo,
    tokenMap,
    allowTokenMapAsInitialDetails = true,
    isAllNetworks,
    indexedAccountId,
    isTabView,
    deriveInfo,
    deriveType,
  } = props;
  const navigation = useAppNavigation();
  const intl = useIntl();
  const copyAccountAddress = useCopyAccountAddress();
  const {
    updateTokenMetadata,
    tokenDetails: tokenDetailsContext,
    updateTokenDetails,
  } = useTokenDetailsContext();

  const [settings] = useSettingsPersistAtom();

  const { network, wallet, account } = useAccountData({
    accountId,
    networkId,
    walletId,
  });

  const tokenDetailsKey = `${accountId}_${networkId}`;
  const tokenDetailsCacheKey = `${accountId}_${networkId}_${
    tokenInfo.address ?? ''
  }_${settings.currencyInfo.id}`;
  const tokenMapKey = (tokenInfo as IAccountToken).$key;

  const cachedTokenDetails = useMemo(() => {
    const contextTokenDetails = tokenDetailsContext[tokenDetailsKey]?.data;
    if (contextTokenDetails) {
      return contextTokenDetails;
    }

    const memoryCachedTokenDetails =
      tokenDetailsCache.get(tokenDetailsCacheKey);
    if (memoryCachedTokenDetails) {
      return memoryCachedTokenDetails;
    }

    const tokenFiat =
      allowTokenMapAsInitialDetails && tokenMapKey
        ? tokenMap?.[tokenMapKey]
        : undefined;
    if (!tokenFiat) {
      return undefined;
    }

    return {
      info: tokenInfo,
      ...tokenFiat,
    };
  }, [
    tokenDetailsContext,
    tokenDetailsKey,
    tokenDetailsCacheKey,
    allowTokenMapAsInitialDetails,
    tokenMap,
    tokenMapKey,
    tokenInfo,
  ]);

  const { handleOnReceive } = useReceiveToken({
    accountId,
    networkId,
    walletId,
    indexedAccountId: indexedAccountId ?? '',
  });

  const { isBotWallet, isBotWalletDeactivated } = useBotWalletDeactivatedStatus(
    {
      walletId,
    },
  );
  const isBotWalletReceiveBlocked = shouldBlockBotWalletReceive({
    isBotWallet,
    isBotWalletDeactivated,
  });
  const isBotWalletCopyBlocked = shouldBlockBotWalletCopyAddress({
    isBotWallet,
    isBotWalletDeactivated,
  });

  const tokenDetailsPromiseOptions = useMemo(
    () => ({
      watchLoading: true,
      overrideIsFocused: (isPageFocused: boolean) =>
        isPageFocused && (isTabView ? focusParam : true),
      debounced: POLLING_DEBOUNCE_INTERVAL,
      ...(cachedTokenDetails !== undefined
        ? { initResult: cachedTokenDetails }
        : {}),
    }),
    [cachedTokenDetails, focusParam, isTabView],
  );
  const { result: tokenDetailsResult, isLoading: isLoadingTokenDetails } =
    usePromiseResult(
      async () => {
        const tokensDetails =
          await backgroundApiProxy.serviceToken.fetchTokensDetails({
            accountId,
            networkId,
            contractList: [tokenInfo.address],
          });

        const data = tokensDetails?.[0];

        if (!data) {
          tokenDetailsCache.delete(tokenDetailsCacheKey);
          return undefined;
        }

        tokenDetailsCache.set(tokenDetailsCacheKey, data);
        updateTokenDetails({
          accountId,
          networkId,
          isInit: true,
          data,
        });
        return data;
      },
      [
        accountId,
        networkId,
        tokenInfo.address,
        updateTokenDetails,
        tokenDetailsCacheKey,
      ],
      tokenDetailsPromiseOptions,
    );

  const tokenDetails = tokenDetailsResult ?? cachedTokenDetails;

  useEffect(() => {
    if (!tokenDetails || (isTabView && !focusParam)) {
      return;
    }

    updateTokenMetadata({
      price: tokenDetails.price ?? 0,
      priceChange24h: tokenDetails.price24h ?? 0,
      coingeckoId:
        tokenDetails.info?.coingeckoId ?? tokenInfo.coingeckoId ?? '',
      networkId,
      tokenAddress: tokenInfo.address,
      currency: tokenDetails.currency,
    });
  }, [
    focusParam,
    isTabView,
    networkId,
    tokenDetails,
    tokenInfo.address,
    tokenInfo.coingeckoId,
    updateTokenMetadata,
  ]);

  const showLoadingState = useMemo(() => {
    if (tokenDetails) {
      return false;
    }
    if (tokenDetailsContext[tokenDetailsKey]?.init) {
      return false;
    }
    return isLoadingTokenDetails ?? true;
  }, [
    tokenDetails,
    tokenDetailsContext,
    tokenDetailsKey,
    isLoadingTokenDetails,
  ]);
  const tokenLogoURI = tokenDetails?.info?.logoURI ?? tokenInfo.logoURI;

  const { isSoftwareWalletOnlyUser } = useUserWalletProfile();

  // Scaled-UI (rebase) marker for the swap gate below; also passed into
  // `pushSwapFromTokenDetails` so its fail-closed re-check sees the same
  // snapshot the disabled state was derived from. While the details request
  // is still in flight (or the tab opted out of the tokenMap seed), fall back
  // to the route token so the loading window stays fail closed instead of
  // treating a scaled-UI token as a plain one.
  const tokenDetailsBalanceMultiplier =
    tokenRebaseUtils.pickBalanceMultiplier(tokenDetails) ??
    tokenInfo.balanceMultiplier;

  const handleOnSwap = useCallback(
    () =>
      pushSwapFromTokenDetails({
        navigation,
        token: {
          address: tokenInfo.address,
          symbol: tokenInfo.symbol,
          isNative: tokenInfo.isNative,
          decimals: tokenInfo.decimals,
          name: tokenInfo.name,
          logoURI: tokenInfo.logoURI,
          balanceMultiplier: tokenDetailsBalanceMultiplier,
        },
        networkId,
        networkLogoURI: network?.logoURI,
        deriveType,
        walletType: wallet?.type,
        isSoftwareWalletOnlyUser,
      }),
    [
      wallet?.type,
      network?.logoURI,
      navigation,
      networkId,
      tokenInfo.address,
      tokenInfo.symbol,
      tokenInfo.isNative,
      tokenInfo.decimals,
      tokenInfo.name,
      tokenInfo.logoURI,
      tokenDetailsBalanceMultiplier,
      deriveType,
      isSoftwareWalletOnlyUser,
    ],
  );

  const disableSwapAction = useMemo(
    () =>
      accountUtils.isUrlAccountFn({ accountId }) ||
      isSwapEntryDisabledToken({
        contractAddress: tokenInfo.address,
        isNative: tokenInfo.isNative,
        networkId,
      }) ||
      // Scaled-UI tokens: Swap would display/build on the raw basis, out of
      // sync with the wallet display.
      tokenRebaseUtils.isScalingBalanceMultiplier(
        tokenDetailsBalanceMultiplier,
      ),
    [
      accountId,
      networkId,
      tokenDetailsBalanceMultiplier,
      tokenInfo.address,
      tokenInfo.isNative,
    ],
  );

  const handleSendPress = useCallback(() => {
    defaultLogger.wallet.walletActions.actionSend({
      walletType: wallet?.type ?? '',
      networkId: network?.id ?? '',
      source: 'tokenDetails',
      isSoftwareWalletOnlyUser,
    });
    navigation.pushModal(EModalRoutes.SignatureConfirmModal, {
      screen: EModalSignatureConfirmRoutes.TxDataInput,
      params: {
        networkId,
        accountId,
        isNFT: false,
        token: tokenDetails?.info ?? tokenInfo,
        isAllNetworks,
        disableAddressTypeSelector: true,
        showAddressTypeSelectorWhenDisabled: !accountUtils.isOthersWallet({
          walletId,
        }),
      },
    });
  }, [
    wallet?.type,
    network?.id,
    isSoftwareWalletOnlyUser,
    navigation,
    networkId,
    accountId,
    tokenDetails?.info,
    tokenInfo,
    isAllNetworks,
    walletId,
  ]);

  const isWatchOnly = useMemo(
    () => wallet?.type === WALLET_TYPE_WATCHING,
    [wallet?.type],
  );

  const { hideAccountAddress } = useDisplayAccountAddress({ networkId });
  const shouldShowAddressBlock = useMemo(() => {
    if (networkUtils.isLightningNetworkByNetworkId(networkId)) return false;

    if (wallet?.type === WALLET_TYPE_HD && !wallet?.backuped) return false;

    if (hideAccountAddress) return false;

    return true;
  }, [wallet?.type, networkId, wallet?.backuped, hideAccountAddress]);

  const addressBlockLabel = useMemo(
    () =>
      intl.formatMessage({
        id: ETranslations.global_my_address,
      }),
    [intl],
  );

  const addressBlockValue = useMemo(() => {
    const address = account?.address ?? '';

    // For deactivated bot wallets the address must not be exposed in full —
    // copying is blocked, and showing the full string would let users still
    // grab the address via long-press / OS-level select. Mask it the same
    // way the account selector shortens addresses.
    if (isBotWalletCopyBlocked) {
      return accountUtils.shortenAddress({ address });
    }

    if (
      accountUtils.isHwWallet({ walletId }) ||
      accountUtils.isQrWallet({ walletId })
    ) {
      return accountUtils.shortenAddress({ address });
    }

    return address;
  }, [account?.address, walletId, isBotWalletCopyBlocked]);

  const handleCopyAddressPress = useCallback(() => {
    if (isBotWalletCopyBlocked) {
      showBotWalletDisabledToast('copyAddress');
      return;
    }
    void copyAccountAddress({
      accountId,
      networkId,
      token: tokenInfo,
      deriveInfo,
    });
  }, [
    copyAccountAddress,
    accountId,
    networkId,
    tokenInfo,
    deriveInfo,
    isBotWalletCopyBlocked,
  ]);

  return (
    <DebugRenderTracker position="top-right" name="TokenDetailsHeader">
      <>
        {isWatchOnly ? (
          // In tab view the alert must sit at the same offset as the
          // aggregate Overview tab's alert (pt $5), or switching tabs
          // visibly shifts it. Standalone pages keep the tighter offset
          // under the navigation header.
          <Stack pt={isTabView ? '$5' : '$2'} px="$5">
            <Alert
              type="warning"
              icon="ErrorOutline"
              title={intl.formatMessage({
                id: ETranslations.watch_only_alert_do_not_send,
              })}
            />
          </Stack>
        ) : null}
        {/* Overview */}
        <Stack px="$5" py="$5">
          {/* Balance */}
          <TokenDetailsBalanceHero
            isLoading={showLoadingState}
            currency={tokenDetails?.currency}
            fiatValue={tokenDetails?.fiatValue}
            balanceParsed={tokenRebaseUtils.applyBalanceMultiplier({
              amount: tokenDetails?.balanceParsed,
              balanceMultiplier:
                tokenRebaseUtils.pickBalanceMultiplier(tokenDetails),
            })}
          />
          {/* Actions */}
          <RawActions>
            <RawActions.Send
              testID={AssetDetailsTestIDs.sendBtn}
              onPress={handleSendPress}
              trackID="wallet-token-details-send"
            />
            <RawActions.Receive
              testID={AssetDetailsTestIDs.receiveBtn}
              disabled={isWatchOnly || isBotWalletReceiveBlocked}
              allowPressWhenDisabled={isBotWalletReceiveBlocked}
              onPress={async () => {
                if (isBotWalletReceiveBlocked) {
                  showBotWalletDisabledToast('receive');
                  return;
                }
                if (
                  await backgroundApiProxy.serviceAccount.checkIsWalletNotBackedUp(
                    {
                      walletId: wallet?.id ?? '',
                    },
                  )
                ) {
                  return;
                }
                defaultLogger.wallet.walletActions.actionReceive({
                  walletType: wallet?.type ?? '',
                  networkId: network?.id ?? '',
                  source: 'tokenDetails',
                  isSoftwareWalletOnlyUser,
                });
                void handleOnReceive({
                  token: tokenInfo,
                });
              }}
              trackID="wallet-token-details-receive"
            />
            <RawActions.Swap
              testID={AssetDetailsTestIDs.swapBtn}
              onPress={handleOnSwap}
              disabled={disableSwapAction}
              trackID="wallet-token-details-swap"
            />
            <ReviewControl>
              <ActionBuy
                disabled={showLoadingState}
                isTabView={isTabView}
                walletId={wallet?.id ?? ''}
                networkId={networkId}
                accountId={accountId}
                walletType={wallet?.type}
                tokenAddress={tokenInfo.address}
                tokenSymbol={tokenInfo.symbol}
                source="tokenDetails"
                trackID="wallet-token-details-buy"
              />
            </ReviewControl>
          </RawActions>
        </Stack>

        {/* DeFi Entry Block */}
        <TokenDetailsDeFiBlock
          networkId={networkId}
          tokenAddress={tokenInfo.address}
          walletType={wallet?.type}
          tokenLogoURI={tokenLogoURI}
        />
        <TokenDetailsAddressBlock
          shouldShow={shouldShowAddressBlock}
          label={addressBlockLabel}
          address={addressBlockValue}
          onPress={handleCopyAddressPress}
          testID={AssetDetailsTestIDs.copyAddressBtn}
          disabled={isBotWalletCopyBlocked}
        />
        {/* History */}
        <Divider mb="$3" />
      </>
    </DebugRenderTracker>
  );
}

function TokenDetailsHeaderWithTabFocus(props: IProps) {
  const { isFocused } = useTabIsRefreshingFocused();

  return <TokenDetailsHeaderContent {...props} focusParam={isFocused} />;
}

function TokenDetailsHeader(props: IProps) {
  if (props.isTabView) {
    return <TokenDetailsHeaderWithTabFocus {...props} />;
  }

  return <TokenDetailsHeaderContent {...props} focusParam />;
}

export default memo(TokenDetailsHeader);
